  "Invites": { de: "Einladungen", es: "Invitaciones", ca: "Invitacions", zh: "邀请", hi: "आमंत्रण", ar: "دعوات", fr: "Invitations", bn: "আমন্ত্রণ", pt: "Convites", ru: "Приглашения", ur: "دعوتیں", id: "Undangan", ja: "招待", pa: "ਸੱਦੇ", mr: "आमंत्रणे", te: "ఆహ్వానాలు", tr: "Davetler", ta: "அழைப்புகள்", vi: "Những lời mời", ha: "Gayyata", sw: "Mwaliko", tl: "Mga imbita", ko: "초대", fa: "دعوت ها", jv: "Undangan", it: "Inviti", gu: "આમંત્રણો", th: "คำเชิญ" },
