  "Mark it read": { de: "Als gelesen markieren", es: "Marcar como leído", ca: "Marca-ho com a llegit", zh: "标记为已读", hi: "इसे पढ़ा हुआ चिह्नित करें", ar: "وضع علامة كمقروء", fr: "Marquer comme lu", bn: "এটি পড়া হিসাবে চিহ্নিত করুন", pt: "Marcar como lido", ru: "Отметить как прочитанное", ur: "اسے پڑھا ہوا نشان زد کریں", id: "Tandai sebagai dibaca", ja: "既読としてマーク", pa: "ਇਸਨੂੰ ਪੜ੍ਹੋ ਦੇ ਤੌਰ ਤੇ ਨਿਸ਼ਾਨ ਲਗਾਓ", mr: "ते वाचले म्हणून चिन्ह करा", te: "చదువుకున్నట్లు గుర్తించండి", tr: "Okundu olarak işaretle", ta: "அதைப் படித்ததாக குறிக்கவும்", vi: "Đánh dấu là đã đọc", ha: "Alamta karantawa", sw: "Alama kama iliyosomwa", tl: "Markahan bilang nabasa", ko: "읽음으로 표시", fa: "نشان‌گذاری خوانده‌شده", jv: "Tandha wis diwoco", it: "Contrassegna come letto", gu: "તેને વાંચાયું તરીકે ચિહ્ન લગાવો", th: "ทำเครื่องหมายว่าอ่านแล้ว" },
  "Marked as read.": { de: "Als gelesen markiert.", es: "Marcado como leído.", ca: "Marcat com a llegit.", zh: "标记为已读。", hi: "पढ़ा हुआ चिह्नित किया गया।", ar: "تم وضع علامة كمقروء.", fr: "Marqué comme lu.", bn: "পড়া হিসাবে চিহ্নিত করা হয়েছে।", pt: "Marcado como lido.", ru: "Отмечено как прочитанное.", ur: "پڑھا ہوا نشان زد کیا گیا۔", id: "Ditandai sebagai dibaca.", ja: "既読としてマーク済み。", pa: "ਪੜ੍ਹੋ ਦੇ ਤੌਰ ਤੇ ਨਿਸ਼ਾਨ ਬਣਾਇਆ ਗਿਆ।", mr: "वाचले म्हणून चिन्हांकित.", te: "చదువుకున్నట్లు గుర్తించబడింది.", tr: "Okundu olarak işaretlendi.", ta: "படித்ததாக குறிக்கப்பட்டது.", vi: "Đã đánh dấu là đã đọc.", ha: "Alamtace karantawa.", sw: "Alama kama iliyosomwa.", tl: "Markado bilang nabasa.", ko: "읽음으로 표시되었습니다.", fa: "به‌عنوان خوانده‌شده نشان‌گذاری شد.", jv: "Ditandha wis diwoco.", it: "Contrassegnato come letto.", gu: "વાંચાયું તરીકે ચિહ્નિત કર્યું.", th: "ทำเครื่องหมายว่าอ่านแล้ว" },
