  "Ours, no client": { de: "Unseres, kein Kunde", es: "El nuestro, sin cliente", ca: "Nostre, sense client", zh: "我们的，没有客户", hi: "हमारा, कोई क्लायंट नहीं", ar: "لنا، بدون عميل", fr: "Nôtre, pas de client", bn: "আমাদের, ক্লায়েন্ট নেই", pt: "Nosso, sem cliente", ru: "Наше, без клиента", ur: "ہمارا، کوئی کلائنٹ نہیں", id: "Milik kami, tidak ada klien", ja: "自社のもの、クライアントなし", pa: "ਸਾਡਾ, ਕੋਈ ਕਲਾਇੰਟ ਨਹੀ", mr: "आमचा, ग्राहक नाही", te: "మనది, క్లయింట్ లేదు", tr: "Bizimki, müşteri yok", ta: "நமது, கிளையன்ட் இல்லை.", vi: "Của chúng tôi, không có khách hàng", ha: "Namin, babu client", sw: "Chetu, hakuna mteja", tl: "Aamin, walang client", ko: "우리 것, 클라이언트 없음", fa: "مال ما، بدون مشتری", jv: "Punyane awak dhewe, ora ana klien", it: "Nostro, nessun cliente", gu: "આપણું, કોઈ ક્લાયન્ટ નથી", th: "ของเรา ไม่มีลูกค้า" },
