  "Withdrawn.": { de: "Zurückgezogen.", es: "Retirada.", ca: "Retirada.", zh: "已收回。", hi: "वापस लिया गया।", ar: "تم السحب.", fr: "Retiré.", bn: "বাতিল।", pt: "Removido.", ru: "Отозвано.", ur: "واپس لیا گیا۔", id: "Dibatalkan.", ja: "取り下げられました。", pa: "ਵਾਪਸ ਕਰ ਦਿਆ ਗਿਆ।", mr: "वापस घेतले.", te: "ఉపసంహరించారు.", tr: "Geri çekildi.", ta: "திரும்பப் பெறப்பட்டது.", vi: "Đã rút lại.", ha: "An janye.", sw: "Imeondolewa.", tl: "Binawi.", ko: "철회됨.", fa: "پس گرفته شد.", jv: "Ditarik balik.", it: "Ritirato.", gu: "પાછું લેવાયું.", th: "ยกเลิกแล้ว" },
