  "e.g. Ticket type": { de: "z.B. Ticket-Typ", es: "p.ej. Tipo de ticket", ca: "p. ex. Tipus de tiquet", zh: "例如 工单类型", hi: "उदा. टिकट प्रकार", ar: "مثال: نوع التذكرة", fr: "e.g. Type de ticket", bn: "উদাহরণ: টিকিটের ধরন", pt: "ex. Tipo de ticket", ru: "например тип заявки", ur: "مثلاً ٹکٹ کی قسم", id: "e.g. Jenis tiket", ja: "例：チケットタイプ", pa: "ਉਦਾਹਰਨ ਲਈ ਟਿਕਟ ਕਿਸਮ", mr: "उदा. तिकीट प्रकार", te: "e.g. టిక్కెట్ రకం", tr: "örn. Talep türü", ta: "எ.கா. டிக்கெட் வகை", vi: "ví dụ Loại yêu cầu", ha: "e.g. Nau'in tikiti", sw: "mfano aina ya tikiti", tl: "halimbawa uri ng ticket", ko: "예: 티켓 유형", fa: "e.g. نوع درخواست", jv: "contone Jenis tiket", it: "es. Tipo di ticket", gu: "ઉ.દા. ટિકિટ પ્રકાર", th: "เช่น ประเภทตั๋ว" },
  "e.g. a question mark": { de: "z.B. ein Fragezeichen", es: "p.ej. un signo de interrogación", ca: "p. ex. un signe d'interrogació", zh: "例如 问号", hi: "उदा. एक प्रश्न चिह्न", ar: "مثال: علامة استفهام", fr: "e.g. un point d'interrogation", bn: "উদাহরণ: একটি প্রশ্ন চিহ্ন", pt: "ex. um ponto de interrogação", ru: "например знак вопроса", ur: "مثلاً سوال کا نشان", id: "e.g. tanda tanya", ja: "例：疑問符", pa: "ਉਦਾਹਰਨ ਲਈ ਸਵਾਲ ਦਾ ਨਿਸ਼ਾਨ", mr: "उदा. प्रश्नचिन्ह", te: "e.g. ప్రశ్న గుర్తు", tr: "örn. bir soru işareti", ta: "எ.கா. ஒரு கேள்விக் குறி", vi: "ví dụ dấu hỏi", ha: "e.g. alamar tambaya", sw: "mfano alama ya swali", tl: "halimbawa isang katanungang marka", ko: "예: 물음표", fa: "e.g. علامت سؤال", jv: "contone tandha pitakonan", it: "es. un punto interrogativo", gu: "ઉ.દા. પ્રશ્ન ચિહ્ન", th: "เช่น เครื่องหมายคำถาม" },
  "e.g. the two dispatchers, and whoever is on the counter": { de: "z.B. die beiden Versandmitarbeiter und wer an der Theke ist", es: "p.ej. los dos despachadores, y quien esté en el mostrador", ca: "p. ex. els dos encarregats d'enviaments, i qualsevol que estigui a la recepció", zh: "例如 两位派遣员，以及柜台上的任何人", hi: "उदा. दोनों डिस्पैचर, और काउंटर पर कोई भी", ar: "مثال: الموزعان، وأي شخص في العداد", fr: "e.g. les deux expéditeurs, et celui qui est à la réception", bn: "উদাহরণ: দুজন ডিসপ্যাচার এবং কাউন্টারে থাকা যে কেউ", pt: "ex. os dois despachantes e quem estiver no balcão", ru: "например двоих диспетчеров и того, кто работает в офисе", ur: "مثلاً دونوں بھیجنے والے، اور جو کاؤنٹر پر ہے", id: "e.g. dua petugas pengiriman, dan siapa pun yang di konter", ja: "例：2 人の配送担当者とカウンター係", pa: "ਉਦਾਹਰਨ ਲਈ ਦੋਵੇਂ ਭੇਜਣ ਵਾਲੇ, ਅਤੇ ਜੋ ਕੋਈ ਕਾਊਂਟਰ ਤੇ ਹੈ", mr: "उदा. दोन पाठवणी कर्मचारी, आणि जो काउंटरवर आहे", te: "e.g. ఇద్దరు పంపిణీదారులు, మరియు కౌంటర్‌పై ఎవరైనా", tr: "örn. iki gönderim görevlisi ve kasa başındaki kimse", ta: "எ.கா. இரண்டு அனுப்புபவர்கள், மற்றும் கவுண்டரில் யார் இருக்கிறார்கள்", vi: "ví dụ như hai nhân viên điều phối, và người bất kỳ đang ở quầy", ha: "e.g. masu aika biyu, da kowa da ke kan gabas", sw: "mfano wasambaza wawili, na yeyote anayekuwa kwenye kaunta", tl: "halimbawa ang dalawang dispatchers, at sinumang nasa counter", ko: "예를 들어, 두 명의 디스패처와 카운터에 있는 사람", fa: "e.g. دو ارسال‌کننده، و هر کسی‌که در پیشخوان است", jv: "contone loro pangiriman, lan sapa wae sing ana ing counter", it: "es. i due spedizionieri e chiunque sia al banco", gu: "ઉ.દા. બે ડિસ્પેચરો અને જે કોઈ કાઉન્ટર પર હોય તો", th: "เช่น คนส่งของสองคน และใครก็ตามที่อยู่ที่เคาน์เตอร์" },
